(function(){const close=()=>{const o=document.getElementById('duty-ov');if(o){o.remove();document.body.classList.remove('asg-lock')}};
 const show=id=>{const m=MEM().find(x=>x.id===id),du=dutyOf(m);if(!du)return;close();const t=m.group&&m.group!==PG?window.tierOfRole(m.role)[0]:'';
  const o=document.createElement('div');o.id='duty-ov';o.className='duty-ov';o.innerHTML=`<div class="duty-box ${t}" role="dialog" aria-modal="true" aria-labelledby="duty-h"><div class="duty-hd"><div><span>ОБЯЗАННОСТИ</span><h3 id="duty-h">${esc(m.role||'')}</h3><small>${esc(m.name||'')}${du.r?' · подчиняется '+esc(du.r):''}</small></div><button class="duty-x" aria-label="Закрыть">✕</button></div><ul>${du.d.map(d=>`<li>${esc(d)}</li>`).join('')}</ul></div>`;
  o.addEventListener('click',e=>{if(e.target===o||e.target.closest('.duty-x'))close()});document.body.appendChild(o);document.body.classList.add('asg-lock');o.querySelector('.duty-x').focus()};
 const hit=e=>{const b=e.target.closest&&e.target.closest('[data-duties]');if(!b)return;e.preventDefault();e.stopPropagation();show(b.dataset.duties)};
 document.addEventListener('click',hit,true);document.addEventListener('keydown',e=>{if(e.key==='Escape')close();else if((e.key==='Enter'||e.key===' ')&&e.target.matches&&e.target.matches('[data-duties]'))hit(e)},true);addEventListener('hashchange',close)})();
