fetch('version.json?t='+Date.now(),{cache:'no-store'}).then(r=>r.json()).then(j=>{window.VPPKA_VER=j.label||'';const put=()=>{const e=document.getElementById('sitever');if(e&&j.label&&e.textContent!=='Версия сайта '+j.label)e.textContent='Версия сайта '+j.label};put();new MutationObserver(put).observe(document.body,{childList:true,subtree:true})}).catch(()=>{});

// Шторка «О партии» в меню.
(function(){const d=document.getElementById('ndd-about');if(!d)return;const t=d.querySelector('.ndd-t'),m=d.querySelector('.ndd-m'),its=()=>[...m.querySelectorAll('a')];
 const set=o=>{d.classList.toggle('open',o);t.setAttribute('aria-expanded',o)};
 const mark=()=>{const k=(location.hash.slice(1)||'home').split('/')[0];t.classList.toggle('on',its().some(a=>a.getAttribute('href')==='#'+k));set(false);setTimeout(scr,50)},scr=()=>{const a=document.querySelector('.ab-tabs a.on');if(a)a.parentNode.scrollLeft=Math.max(0,a.offsetLeft-a.parentNode.offsetLeft-16)};
 t.addEventListener('click',e=>{e.preventDefault();set(!d.classList.contains('open'))});
 t.addEventListener('keydown',e=>{if(e.key==='ArrowDown'||e.key==='Enter'||e.key===' '){if(e.key!=='ArrowDown'&&d.classList.contains('open'))return;e.preventDefault();set(true);its()[0].focus()}});
 m.addEventListener('keydown',e=>{const a=its(),i=a.indexOf(document.activeElement);if(e.key==='ArrowDown'){e.preventDefault();a[(i+1)%a.length].focus()}else if(e.key==='ArrowUp'){e.preventDefault();a[(i-1+a.length)%a.length].focus()}else if(e.key==='Home'){e.preventDefault();a[0].focus()}else if(e.key==='End'){e.preventDefault();a[a.length-1].focus()}});
 d.addEventListener('keydown',e=>{if(e.key==='Escape'&&d.classList.contains('open')){e.stopPropagation();set(false);t.focus()}});
 d.addEventListener('focusout',e=>{if(!d.contains(e.relatedTarget))set(false)});
 document.addEventListener('click',e=>{if(!d.contains(e.target))set(false)});
 m.addEventListener('click',e=>{if(e.target.closest('a'))set(false)});
 addEventListener('hashchange',mark);addEventListener('load',()=>setTimeout(scr,600));mark()})();
